Tabulator = require("tabulator-tables@5.5.2")
idb = require("idb@8.0.0/build/umd.js")
















db = idb.openDB("OutlierReviewDB", 1, {
  upgrade(db) {
    if (!db.objectStoreNames.contains("reviews")) {
      db.createObjectStore("reviews", { keyPath: "identifier" });
    }
  }
})

// Helper to save or update an edited record
saveReview = async (record) =&gt; {
  if (!record || !record.identifier) return;
  const database = await db;
  await database.put("reviews", record);
}

// Helper to retrieve all saved records for CSV download
getAllSavedReviews = async () =&gt; {
  const database = await db;
  return await database.getAll("reviews");
}

// Helper to get saved state for a specific set of records
getSavedReviewsMap = async () =&gt; {
  const database = await db;
  const all = await database.getAll("reviews");
  return new Map(all.map(item =&gt; [item.identifier, item.decision]));
}

// Trigger to tell our dropdowns when to recalculate checkmarks
mutable idbTrigger = 0;

// Reactive map of all decisiones across the entire dataset
globalDecisionMap = {
  idbTrigger;

  const map = new Map();
  // Base decisiones from original dataset
  pce_outliers_log.forEach(d =&gt; {
    if (d.decision) map.set(d.identifier, d.decision);
  });

  // Overrides from IDB
  const saved = await getAllSavedReviews();
  saved.forEach(d =&gt; {
    if (d.decision) map.set(d.identifier, d.decision);
  });

  return map;
}












































Outlier Review

pce_outliers_log = FileAttachment("data/l2/logs/l2_pce_imputation_options.csv")
  .csv()
  .then(data =&gt; {
    return data.map(d =&gt; {
      let cleanedRow = {};

      for (let key in d) {
        let val = d[key];

        if (val === "" || val === "NA" || val === null || val === undefined) {
          cleanedRow[key] = null;
        }
        else if (key === "date" || isNaN(val) || isNaN(Number(val))) {
          cleanedRow[key] = val;
        }
        else {
          cleanedRow[key] = Number(val);
        }
      }

      if (!cleanedRow.decision) {
        cleanedRow.decision = null;
      }

      return cleanedRow;
    })
  })

// L1 PCE
pce = FileAttachment("data/l1/consolidated/l1_pce.csv")
  .csv()
  .then(data =&gt; {
    return data.map(d =&gt; {
      let cleanedRow = {};

      for (let key in d) {
        let val = d[key];

        if (val === "" || val === "NA" || val === null || val === undefined) {
          cleanedRow[key] = null;
        }
        else if (key === "date" || isNaN(val) || isNaN(Number(val))) {
          cleanedRow[key] = val;
        }
        else {
          cleanedRow[key] = Number(val);
        }
      }

      return cleanedRow;
    })
    .sort((a, b) =&gt; new Date(a.date) - new Date(b.date));
  })
















communities = [...new Set(pce_outliers_log.map(d =&gt; d.sales_reporting_name))]
mutable currentComm = communities[0]

// Build dynamic options with emojis
communityOptions = new Map(communities.map(comm =&gt; {
  const commData = pce_outliers_log.filter(d =&gt; d.sales_reporting_name === comm);
  const isComplete = commData.every(d =&gt; globalDecisionMap.get(d.identifier));

  return [isComplete ? `🍏 ${comm}` : comm, comm]; 
}))

viewof selectedCommunity = {
  const el = Inputs.select(communityOptions, { label: "Community:", value: currentComm });
  el.addEventListener("input", () =&gt; { mutable currentComm = el.value; });
  return el;
}

availableColumns = {
  const subset = pce_outliers_log.filter(d =&gt; d.sales_reporting_name === currentComm);
  return [...new Set(subset.map(d =&gt; d.column))];
}
mutable currentCol = availableColumns[0]

columnOptions = new Map(availableColumns.map(col =&gt; {
  const colData = pce_outliers_log.filter(d =&gt; 
    d.sales_reporting_name === currentComm && d.column === col
  );
  const isComplete = colData.every(d =&gt; globalDecisionMap.get(d.identifier));

  return [isComplete ? `🍏 ${col}` : col, col];
}))

viewof selectedColumn = {
  const validCol = availableColumns.includes(currentCol) ? currentCol : availableColumns[0];
  if (currentCol !== validCol) mutable currentCol = validCol;

  const el = Inputs.select(columnOptions, { label: "Column:", value: validCol });
  el.addEventListener("input", () =&gt; { mutable currentCol = el.value; });
  return el;
}

strategyMap = new Map([
  ["Keep original value", "raw_value"],
  ["Carry forward", "carry_forward"],
  ["Annual average", "annual_average"],
  ["Average of preceding and proceeding months", "avg_preceding_proceeding"],
  ["Average of months from other years", "avg_same_month_other_years"],
  ["Manual override", "manual_override"]
])

































































filteredFullSeries = pce.filter(d =&gt;
  d.sales_reporting_name === currentComm
)

viewof hideDecided = Inputs.toggle({ 
  label: html`&lt;b&gt;Hide decided&lt;/b&gt;`, 
  value: true 
})

// Filter outliers based on imputation selection
imputedOutlierDots = outlierTableData.map(d =&gt; {
  const colName = strategyMap.get(d.decision);
  const imputedVal = colName ? d[colName] : null;

  return {
    ...d,
    imputed_value: imputedVal
  };
})























// Plot lines, outlier dots (red), imputed preview dots (green), table hover rings (orange), and smart tooltip

chartContainer = {
  hoveredId; 

  const container = html`&lt;div style="min-height: 500px; width: 100%;"&gt;&lt;/div&gt;`;

  const activeImputedDots = imputedOutlierDots.filter(d =&gt; d.imputed_value !== null);

  const unifiedTooltipData = [];
  const outlierDates = new Set(outlierTableData.map(d =&gt; String(d.date)));

  // Gray dots
  filteredFullSeries.forEach(d =&gt; {
    if (!outlierDates.has(String(d.date))) {
      unifiedTooltipData.push({ 
        ...d, tip_x: d.date, tip_y: d[currentCol], tip_type: "Original Value" 
      });
    }
  });

  // Red dots
  outlierTableData.forEach(d =&gt; {
    const raw_y = d.raw_value ?? d[currentCol];
    if (d.imputed_value !== raw_y) {
      unifiedTooltipData.push({ 
        ...d, tip_x: d.date, tip_y: raw_y, tip_type: "Raw Outlier" 
      });
    }
  });

  // Green dots
  activeImputedDots.forEach(d =&gt; {
    unifiedTooltipData.push({ 
      ...d, tip_x: d.date, tip_y: d.imputed_value, tip_type: "Imputed Value" 
    });
  });

  // Data from table hover
  const hoveredData = hoveredId 
    ? unifiedTooltipData.filter(d =&gt; d.identifier === hoveredId) 
    : [];

  const plot = Plot.plot({
    height: 500,
    width: width,
    marginLeft: 60,
    grid: false,
    x: { type: "utc", label: "Date", ticks: 20, tickFormat: "%Y" },
    y: { label: currentCol !== "All" ? currentCol : "Value", grid: true },
    marks: [
      Plot.line(filteredFullSeries, { x: "date", y: d =&gt; d[currentCol], stroke: "#ccc", strokeWidth: 1.5 }),
      Plot.dot(filteredFullSeries, { x: "date", y: d =&gt; d[currentCol], fill: "#888888", r: 3 }),
      Plot.dot(outlierTableData, { x: "date", y: d =&gt; d.raw_value ?? d[currentCol], fill: "red", stroke: "black", strokeWidth: 1, r: 6 }),
      Plot.dot(activeImputedDots, { x: "date", y: "imputed_value", fill: "#2ca02c", stroke: "black", strokeWidth: 1.5, r: 7 }),

      // Highlight ring on table hover
      Plot.dot(hoveredData, {
        x: "tip_x",
        y: "tip_y",
        r: 13,
        stroke: "#ff9900",
        strokeWidth: 3,
        fill: "none"
      }),

      // Tooltip on table hover
      Plot.tip(hoveredData, {
          x: "tip_x",
          y: "tip_y",
          dy: -5,
          channels: {
              "Community": "sales_reporting_name", "Year": "calendar_year", "Month": "calendar_month",
              "Point Type": "tip_type", "Value": "tip_y", "Comment": "comment"
          },
          format: { x: false, y: false }
      }),

      // Smart tooltip
      Plot.tip(unifiedTooltipData, Plot.pointer({
          x: "tip_x",
          y: "tip_y",
          maxRadius: 15,
          channels: {
              "Community": "sales_reporting_name", "Year": "calendar_year", "Month": "calendar_month",
              "Point Type": "tip_type", "Value": "tip_y", "Comment": "comment"
          },
          format: { x: false, y: false }
      }))
    ]
  });

  container.appendChild(plot);
  return container;
}







// Tracks the ID of the row hovered in the table
mutable hoveredId = null;







// Tabulator Table with IDB Hydration & Persistence

viewof outlierTableData = {
  hideDecided; 

  const initialData = pce_outliers_log.filter(d =&gt;
    d.sales_reporting_name === currentComm &&
    d.column === currentCol
  );

  const savedMap = await getSavedReviewsMap();
  const hydratedData = initialData.map(row =&gt; {
    if (savedMap.has(row.identifier)) {
      return { 
        ...row, 
        decision: savedMap.get(row.identifier),
        manual_override: savedMap.has(row.identifier) ? undefined : row.manual_override
      };
    }
    return row;
  });

  const allSaved = await getAllSavedReviews();
  const savedDict = Object.fromEntries(allSaved.map(item =&gt; [item.identifier, item]));

  const fullyHydratedData = initialData.map(row =&gt; {
    if (savedDict[row.identifier]) {
      return { ...row, ...savedDict[row.identifier] };
    }
    return row;
  });

  const container = html`&lt;div style="margin-bottom: 20px; width: 100%;"&gt;&lt;/div&gt;`;

  const table = new Tabulator(container, {
    data: JSON.parse(JSON.stringify(fullyHydratedData)),
    layout: "fitData",
    maxHeight: "400px",
    headerWordWrap: true,
    columnDefaults: {
      minWidth: 30, // in pixels
      headerSort: false,
    },
    columns: [
      { title: "PCE ID", field: "project_code" },
      { title: "Name", field: "sales_reporting_name", maxWidth: 90 },
      { title: "Year", field: "calendar_year", maxWidth: 70 },
      { title: "Month", field: "calendar_month", maxWidth: 75 },
      { title: "Column", field: "column", maxWidth: 170},
      { title: "Orig Value", field: "raw_value" },
      { title: "Carry Fwd", field: "carry_forward" },
      { title: "Annual Avg", field: "annual_average" },
      { title: "Pre/Post Avg", field: "avg_preceding_proceeding" },
      { title: "Same Month Avg", field: "avg_same_month_other_years" , maxWidth: 150},
      { 
        title: "Manual Value", 
        field: "manual_override", 
        editor: "number",
        editorParams: {
          step: "any"
        },
        maxWidth: 100
      },
      {
        title: "Override Action",
        field: "decision",
        editor: "list",
        editorParams: {
          values: [
            "Keep original value",
            "Carry forward",
            "Annual average",
            "Average of preceding and proceeding months",
            "Average of months from other years",
            "Manual override"
          ]
        },
        maxWidth: 150
      },
      {
        title: "Comment",
        field: "comment",
        editor: "input",
        maxWidth: 100
      }
    ]
  });

  // Apply the filter if 'hide decided' toggle checked
  if (hideDecided) {
    table.setFilter(row =&gt; {
      return !row.decision || row.decision.trim() === "";
    });
  }

  const updateData = async (cell) =&gt; {
    if (cell) {
      const row = cell.getRow();
      const field = cell.getField();

      if (field === "manual_override") {
        const val = cell.getValue();
        if (val !== null && val !== "" && !isNaN(val)) {
          await row.update({ decision: "Manual override" });
        }
      }

      const rowData = row.getData();
      await saveReview(rowData); 
      mutable idbTrigger++; 
    }

    container.value = table.getData();
    container.dispatchEvent(new CustomEvent("input"));
  };

  table.on("rowMouseEnter", (e, row) =&gt; {
    mutable hoveredId = row.getData().identifier;
  });

  table.on("rowMouseLeave", () =&gt; {
    mutable hoveredId = null;
  });

  table.on("cellEdited", updateData);
  table.on("tableBuilt", () =&gt; updateData());

  container.value = fullyHydratedData;
  return container;
}







// Download Button

// Generate download button
downloadAction = {
  const btn = html`&lt;button class="btn btn-primary my-3"&gt;&lt;i class="bi bi-download me-1"&gt;&lt;/i&gt; Download All Decisions (CSV)&lt;/button&gt;`;

  btn.onclick = async () =&gt; {
    const savedRecords = await getAllSavedReviews();

    if (!savedRecords || savedRecords.length === 0) {
      alert("No saved overrides found in local storage.");
      return;
    }

    const allKeys = Array.from(new Set(savedRecords.flatMap(Object.keys)));
    const headers = allKeys.join(",");

    const rows = savedRecords.map(row =&gt;
      allKeys.map(key =&gt; {
        let val = row[key];

        if (key === "decision" && val) {
          val = strategyMap.get(val) || val;
        }

        let safeVal = String(val ?? '');

        // escape double quotes
        safeVal = safeVal.replace(/"/g, '""');

        // wrap in quotes
        return `"${safeVal}"`;
      }).join(",")
    );

    const csvContent = [headers, ...rows].join("\n");

    // Trigger browser download
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `outlier_reviews_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return btn;
}
